<?php require_once __DIR__.'/../includes/auth.php'; require_role('HEALTHCARE');
$o=my_org($pdo); $oid=$o['organization_id']; [$f,$t]=date_range(date('Y-m-01'),date('Y-m-d'));
function grp($pdo,$sql,$p){ $s=$pdo->prepare($sql); $s->execute($p); return $s->fetchAll(PDO::FETCH_KEY_PAIR); }
$req=grp($pdo,"SELECT IF(r.status='CANCELLED' AND ".AUTOCLOSED_SQL.",'EXPIRED (auto-closed)',IF(r.status='CANCELLED','CANCELLED (by organization)',r.status)) s,COUNT(*) FROM emergency_requests r WHERE r.organization_id=? AND DATE(r.created_at) BETWEEN ? AND ? GROUP BY s",[$oid,$f,$t]);
$urg=grp($pdo,"SELECT urgency,COUNT(*) FROM emergency_requests WHERE organization_id=? AND DATE(created_at) BETWEEN ? AND ? GROUP BY urgency",[$oid,$f,$t]);
$mat=grp($pdo,"SELECT m.status,COUNT(*) FROM donor_matches m JOIN emergency_requests r USING(request_id) WHERE r.organization_id=? AND DATE(m.matched_at) BETWEEN ? AND ? GROUP BY m.status",[$oid,$f,$t]);
$don=grp($pdo,"SELECT donation_type,SUM(units_donated) FROM donations WHERE organization_id=? AND status='COMPLETED' AND DATE(donation_date) BETWEEN ? AND ? GROUP BY donation_type",[$oid,$f,$t]);
$rec=grp($pdo,"SELECT blood_group,SUM(quantity_change) FROM inventory_logs WHERE organization_id=? AND change_type IN ('DONATION','RESTOCK') AND quantity_change>0 AND DATE(created_at) BETWEEN ? AND ? GROUP BY blood_group",[$oid,$f,$t]);
$use=grp($pdo,"SELECT blood_group,SUM(-quantity_change) FROM inventory_logs WHERE organization_id=? AND change_type='EMERGENCY_USE' AND DATE(created_at) BETWEEN ? AND ? GROUP BY blood_group",[$oid,$f,$t]);
$exp=grp($pdo,"SELECT blood_group,SUM(-quantity_change) FROM inventory_logs WHERE organization_id=? AND change_type='EXPIRED' AND DATE(created_at) BETWEEN ? AND ? GROUP BY blood_group",[$oid,$f,$t]);
$scr=grp($pdo,"SELECT CASE b.status WHEN 'QUARANTINE' THEN 'Pending screening' WHEN 'REJECTED' THEN 'Rejected (reactive)' ELSE 'Passed (released to stock / used / expired)' END s,SUM(n.units_donated) FROM donations n JOIN blood_batches b ON b.donation_id=n.donation_id WHERE n.organization_id=? AND n.status='COMPLETED' AND DATE(n.donation_date) BETWEEN ? AND ? GROUP BY s",[$oid,$f,$t]);
$camp=$pdo->prepare("SELECT c.campaign_id,c.campaign_name,c.campaign_date,c.status,COUNT(n.donation_id) dn,COALESCE(SUM(b.status='QUARANTINE'),0) q,COALESCE(SUM(b.status IN ('ACTIVE','USED','EXPIRED')),0) ok,COALESCE(SUM(b.status='REJECTED'),0) rj FROM donation_campaigns c LEFT JOIN donations n ON n.campaign_id=c.campaign_id LEFT JOIN blood_batches b ON b.donation_id=n.donation_id WHERE c.organization_id=? AND c.campaign_date BETWEEN ? AND ? GROUP BY c.campaign_id ORDER BY c.campaign_date DESC"); $camp->execute([$oid,$f,$t]); $camp=$camp->fetchAll();
$cg=$pdo->prepare("SELECT n.campaign_id,n.blood_group,SUM(n.units_donated) u FROM donations n JOIN donation_campaigns c ON c.campaign_id=n.campaign_id WHERE c.organization_id=? AND c.campaign_date BETWEEN ? AND ? GROUP BY n.campaign_id,n.blood_group ORDER BY n.blood_group"); $cg->execute([$oid,$f,$t]); $cgm=[]; foreach($cg->fetchAll() as $r) $cgm[$r['campaign_id']][]=$r['blood_group'].': '.$r['u'];
$inv=$pdo->prepare("SELECT * FROM blood_inventory WHERE organization_id=? ORDER BY blood_group"); $inv->execute([$oid]);
$title='Operational Report'; require '../includes/header.php';
function tb($a,$h){ echo "<div class='card'><b>$h</b><table>"; foreach($a as $k=>$v) echo "<tr><td>".h($k)."</td><td>".h($v)."</td></tr>"; if(!$a) echo "<tr><td class='muted'>No data</td></tr>"; echo "</table></div>"; } ?>
<form class="filter"><label class="dl">Report from <input type="date" name="from" value="<?= h($f) ?>"></label><label class="dl">Report to <input type="date" name="to" value="<?= h($t) ?>"></label><button class="btn">Generate</button><button type="button" class="btn alt" onclick="window.print()">Print</button></form>
<div class="row"><?php tb($req,'Requests by status'); tb($urg,'Requests by urgency'); tb($mat,'Donor matches'); tb($don,'Units collected by type'); tb($scr,'Screening outcome of units collected'); tb($use,'Units issued (emergency use)'); ?></div>
<h2>Campaign summary</h2><p class="muted">Campaigns held in the selected period: units collected by blood group and the screening outcome (tested = released to stock or already used; pending = still in quarantine; rejected = reactive).</p>
<div class="tw"><table><thead><tr><th>Campaign</th><th>Date</th><th>Status</th><th>Units collected</th><th>By group</th><th>Tested OK</th><th>Pending</th><th>Rejected</th></tr></thead><tbody>
<?php foreach($camp as $c): ?><tr><td><?= h($c['campaign_name']) ?></td><td><?= h($c['campaign_date']) ?></td><td><?= badge($c['status']) ?></td><td><?= (int)$c['dn'] ?></td><td><?= h(implode(', ',$cgm[$c['campaign_id']]??[])?:'-') ?></td><td><?= (int)$c['ok'] ?></td><td><?= (int)$c['q'] ?></td><td><?= (int)$c['rj'] ?></td></tr><?php endforeach; if(!$camp) echo "<tr><td colspan='8' class='muted'>No campaigns in this period</td></tr>"; ?></tbody></table></div>
<h2>Expiry wastage</h2><p class="muted">Units discarded because they passed their expiry date, compared with units received (donations + restocks) in the selected period.</p>
<div class="tw"><table><thead><tr><th>Group</th><th>Received</th><th>Expired / discarded</th><th>Wastage %</th></tr></thead><tbody>
<?php $tr=0;$te=0; foreach(BLOOD as $b){ $r=(int)($rec[$b]??0); $e=(int)($exp[$b]??0); if(!$r&&!$e) continue; $tr+=$r;$te+=$e; echo "<tr><td>".h($b)."</td><td>$r</td><td>$e</td><td>".($r?round($e*100/$r,1).'%':'-')."</td></tr>"; }
if(!$tr&&!$te) echo "<tr><td colspan='4' class='muted'>No stock received or expired in this period</td></tr>"; else echo "<tr><td><b>Total</b></td><td><b>$tr</b></td><td><b>$te</b></td><td><b>".($tr?round($te*100/$tr,1).'%':'-')."</b></td></tr>"; ?></tbody></table></div>
<h2>Current inventory</h2><div class="tw"><table><thead><tr><th>Group</th><th>Units</th><th>Minimum</th><th>Alert</th></tr></thead><tbody>
<?php foreach($inv as $r) echo "<tr><td>".h($r['blood_group'])."</td><td>{$r['units_available']}</td><td>{$r['minimum_stock']}</td><td>".($r['units_available']<=$r['minimum_stock']?badge('LOW'):'OK')."</td></tr>"; ?></tbody></table></div>
<?php require '../includes/footer.php';
